from v2.models.knowledge_models import Topic


class NavigationEnricher:
    """
    Génère automatiquement :

    - prerequisites
    - next_topics
    - related_topics

    ainsi que les relations du Knowledge Graph.
    """

    def enrich(self, families):

        for family in families:

            for chapter in family.chapters:

                topics = sorted(
                    chapter.topics,
                    key=lambda topic: topic.editorial_order,
                )

                self._link_sequence(topics)
                self._link_related(topics)

        return families

    # ==========================================================
    # Navigation pédagogique
    # ==========================================================

    def _link_sequence(
        self,
        topics: list[Topic],
    ):

        for index, topic in enumerate(topics):

            # --------------------------------------------------

            if index > 0:

                previous = topics[index - 1]

                if previous.id not in topic.prerequisites:

                    topic.prerequisites.append(previous.id)

                topic.add_relation(
                    target=previous.id,
                    relation_type="prerequisite",
                    score=1.0,
                    source="NavigationEnricher",
                )

            # --------------------------------------------------

            if index < len(topics) - 1:

                nxt = topics[index + 1]

                if nxt.id not in topic.next_topics:

                    topic.next_topics.append(nxt.id)

                topic.add_relation(
                    target=nxt.id,
                    relation_type="next",
                    score=1.0,
                    source="NavigationEnricher",
                )

    # ==========================================================
    # Related
    # ==========================================================

    def _link_related(
        self,
        topics: list[Topic],
    ):

        for topic in topics:

            for other in topics:

                if other.id == topic.id:
                    continue

                if other.id not in topic.related_topics:

                    topic.related_topics.append(other.id)

                topic.add_relation(
                    target=other.id,
                    relation_type="related",
                    score=0.60,
                    source="NavigationEnricher",
                )

