from pathlib import Path

from v2.knowledge.compiler.compiled_knowledge_writer import (
    CompiledKnowledgeWriter,
)
from v2.knowledge.compiler.knowledge_compiler import (
    KnowledgeCompiler,
)
from v2.knowledge.loaders.academic_knowledge_loader import (
    AcademicKnowledgeLoader,
)


class KnowledgeCompilationPipeline:
    """
    Compile automatiquement le corpus académique BRITED.
    """

    def __init__(self):

        self.loader = AcademicKnowledgeLoader()
        self.compiler = KnowledgeCompiler()
        self.writer = CompiledKnowledgeWriter()

    def compile_family(
        self,
        family: str,
    ) -> list[Path]:

        blocks = self.loader.load_family(
            family
        )

        outputs: list[Path] = []

        for block in blocks:

            compiled = self.compiler.compile(
                block
            )

            output = self.writer.write(
                compiled
            )

            outputs.append(output)

        return outputs

